{
  "name": "playground",
  "version": "1.0.0",
  "description": "<!-- omgithub:readme:start --> ## 🚀 Build, play, and remix with OMGithub",
  "main": "index.js",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/paulocesartmofficial-code/PlayGround.git"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "bugs": {
    "url": "https://github.com/paulocesartmofficial-code/PlayGround/issues"
  },
  "homepage": "https://github.com/paulocesartmofficial-code/PlayGround#readme",
  "dependencies": {
    "@fontsource/ibm-plex-mono": "^5.3.0",
    "@fontsource/rajdhani": "^5.3.0",
