input.content:
:root {
  --bg: #070a0c;
  --ink: #eef2ec;
  --muted: #8c979a;
  --dim: #586265;
  --line: rgba(231, 240, 235, 0.14);
  --line-strong: rgba(231, 240, 235, 0.28);
  --accent: #ff9d45;
  --accent-hot: #ff6b2c;
  --accent-soft: rgba(255, 157, 69, 0.14);
  --teal: #96e5cf;
  --danger: #ff4d4d;
  --panel: rgba(10, 14, 16, 0.72);
  --font-display: "Rajdhani", "Arial Narrow", sans-serif;
  --font-mono: "IBM Plex Mono", monospace;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-display);
  overscroll-behavior: none;
  touch-action: none;
}
button { font-family: inherit; color: inherit; }
.hidden { display: none !important; }
#game-root { position: fixed; inset: 0; overflow: hidden; background: #070a0c; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: 0; }

.fx-grain {
  position: absolute; inset: 0; z-index: 30; pointer-events: none; opacity: .14;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
.fx-vignette {
  position: absolute; inset: 0; z-index: 3; pointer-events: none;
  background:
    linear-gradient(90deg, rgba(3,5,6,.58) 0%, transparent 24%, transparent 72%, rgba(3,5,6,.38) 100%),
    radial-gradient(ellipse at center, transparent 38%, rgba(1,3,4,.44) 78%, rgba(1,3,4,.82) 100%);
}
#damage-flash {
  position: absolute; inset: 0; z-index: 40; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 28%, rgba(113,8,8,.2) 62%, rgba(200,19,19,.72) 100%);
  box-shadow: inset 0 0 140px rgba(255,20,20,.6);
  transition: opacity .12s ease-out;
}
#hurt-direction {
  position: absolute; inset: -20%; z-index: 41; pointer-events: none; opacity: 0;
  background: conic-gradient(from var(--hurt-angle, 0deg), transparent 0deg, rgba(255,35,22,.7) 11deg, transparent 27deg);
  filter: blur(18px);
  transition: opacity .18s;
}

/* ============ MENU ============ */
.menu-shell {
  position: absolute; inset: 0; z-index: 20; display: flex; flex-direction: column;
  padding: max(22px, env(safe-area-inset-top)) clamp(24px, 4.4vw, 72px) max(16px, env(safe-area-inset-bottom));
  background:
    linear-gradient(90deg, rgba(4,7,8,.94) 0%, rgba(4,7,8,.64) 36%, rgba(4,7,8,.06) 68%, rgba(4,7,8,.24) 100%),
    linear-gradient(0deg, rgba(4,7,8,.92) 0%, transparent 28%, transparent 80%, rgba(4,7,8,.48) 100%);
  overflow: hidden;
}
.menu-shell::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px;
  background: linear-gradient(180deg, transparent, var(--accent) 18%, var(--accent) 66%, transparent);
  opacity: .6;
}
.topbar {
  flex: none; display: flex; align-items: center; justify-content: space-between;
  height: 58px; border-bottom: 1px solid var(--line); position: relative; z-index: 2;
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 33px; height: 33px; color: var(--accent); display: block; filter: drop-shadow(0 0 12px rgba(255,157,69,.25)); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-copy { display: flex; flex-direction: column; line-height: 1; }
.brand-copy b { font-size: 17px; letter-spacing: .19em; font-weight: 700; }
.brand-copy small { font: 500 8px/1.7 var(--font-mono); letter-spacing: .17em; color: var(--muted); }
.topbar-right { display: flex; align-items: center; gap: 18px; }
.net-status { display: flex; gap: 9px; align-items: center; font: 500 9px/1 var(--font-mono); letter-spacing: .13em; color: var(--muted); }
.net-status i { width: 5px; height: 5px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); }
.net-status b { color: rgba(238,242,236,.64); font-weight: 500; }
.icon-btn { width: 36px; height: 36px; border: 1px solid var(--line); background: rgba(10,15,16,.4); display: grid; place-items: center; cursor: pointer; transition: .2s; }
.icon-btn:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }
.icon-btn svg { width: 18px; height: 18px; }
.icon-off { display: none; }
.sound-off .icon-on { display: none; }
.sound-off .icon-off { display: block; }

.menu-main {
  flex: 1; min-height: 0; display: flex; align-items: center; justify-content: space-between;
  gap: 5vw; position: relative; z-index: 2; padding: 2.4vh 0 2vh;
}
.hero-copy { width: min(660px, 58vw); padding-left: clamp(0px, 1.8vw, 30px); }
.eyebrow { display: flex; align-items: center; gap: 12px; color: var(--accent); font: 500 10px/1 var(--font-mono); letter-spacing: .2em; margin-bottom: 14px; }
.eyebrow-line { display: inline-block; width: 37px; height: 1px; background: var(--accent); }
.eyebrow b { color: rgba(238,242,236,.36); font-weight: 500; }
.hero-copy h1 {
  margin: 0; font-size: clamp(76px, 11.4vw, 174px); font-weight: 700; line-height: .76;
  letter-spacing: .015em; color: #edf1eb; text-shadow: 0 18px 50px rgba(0,0,0,.55);
  position: relative;
}
.hero-copy h1 span {
  color: transparent; -webkit-text-stroke: 1.5px rgba(237,241,235,.55); margin-left: .04em;
}
.hero-copy h1::after {
  content: "BLACKSITE"; position: absolute; left: 2px; top: 3px; z-index: -1;
  color: transparent; -webkit-text-stroke: 1px rgba(0,0,0,.4);
}
.hero-sub { margin-top: 12px; display: flex; align-items: center; gap: 14px; }
.hero-sub b {
  font-size: clamp(17px, 1.8vw, 27px); letter-spacing: .44em; font-weight: 600; color: var(--accent);
  padding: 4px 10px 4px 15px; border-left: 2px solid var(--accent); background: linear-gradient(90deg, rgba(255,157,69,.13), transparent);
}
.hero-sub span { font: 500 8px/1 var(--font-mono); letter-spacing: .28em; color: var(--muted); }
.mission-copy {
  margin: 24px 0 28px; color: rgba(230,237,232,.64); font-size: clamp(13px, 1.15vw, 16px);
  line-height: 1.6; letter-spacing: .055em; font-weight: 500; text-transform: uppercase;
}
.hero-actions { display: flex; align-items: stretch; gap: 12px; }

.primary-btn {
  position: relative; min-width: 270px; border: 1px solid rgba(255,157,69,.7); cursor: pointer;
  background: linear-gradient(110deg, rgba(255,157,69,.97), #f0772d 55%, #d55b1f);
  color: #130d07; height: 66px; padding: 0 18px 0 16px; display: flex; align-items: center; gap: 13px;
  overflow: hidden; text-align: left; transition: transform .18s, box-shadow .18s, filter .18s;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
  box-shadow: 0 12px 40px rgba(255,110,35,.2);
}
.primary-btn:hover { transform: translateY(-2px); box-shadow: 0 16px 48px rgba(255,110,35,.33); filter: brightness(1.05); }
.primary-btn:active { transform: translateY(0); }
.btn-glow { position: absolute; inset: 0; background: linear-gradient(100deg, transparent 20%, rgba(255,255,255,.5), transparent 55%); transform: translateX(-120%); animation: btnSweep 4.5s 1.4s infinite; }
@keyframes btnSweep { 0%, 50% { transform: translateX(-130%); } 70%, 100% { transform: translateX(130%); } }
.btn-icon { width: 32px; height: 32px; border: 1px solid rgba(15,9,4,.26); display: grid; place-items: center; flex: none; background: rgba(20,12,8,.08); }
.btn-icon svg { width: 17px; height: 17px; }
.btn-copy { display: flex; flex-direction: column; gap: 4px; flex: 1; }
.btn-copy b { font-size: 20px; font-weight: 700; letter-spacing: .2em; line-height: 1; }
.btn-copy small { font: 600 7.5px/1 var(--font-mono); letter-spacing: .14em; opacity: .62; }
.btn-arrow { font: 400 23px/1 var(--font-mono); margin-left: 8px; opacity: .85; }
.ghost-btn {
  height: 66px; min-width: 150px; padding: 0 20px; cursor: pointer; border: 1px solid var(--line-strong);
  color: rgba(238,242,236,.66); background: rgba(15,20,22,.38); display: flex; align-items: center; justify-content: center; gap: 10px;
  font: 600 11px/1 var(--font-mono); letter-spacing: .13em; transition: .2s;
}
.ghost-btn:hover { border-color: rgba(255,157,69,.6); color: var(--accent); background: var(--accent-soft); }
.ghost-btn svg { width: 17px; height: 17px; }
.menu-meta { display: flex; gap: 0; margin-top: 30px; border-top: 1px solid var(--line); width: fit-content; }
.menu-meta > div { border-right: 1px solid var(--line); padding: 13px 28px 0 0; margin-right: 28px; }
.menu-meta > div:last-child { border: 0; padding-right: 0; margin: 0; }
.menu-meta small { display: block; font: 500 7.5px/1 var(--font-mono); letter-spacing: .17em; color: var(--dim); margin-bottom: 5px; }
.menu-meta b { font-size: 11px; letter-spacing: .12em; font-weight: 600; color: rgba(238,242,236,.8); }

.dossier {
  width: min(354px, 28vw); flex: none; align-self: center; border: 1px solid rgba(231,240,235,.17);
  background: linear-gradient(150deg, rgba(15,22,23,.86), rgba(8,12,13,.72));
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 34px 100px rgba(0,0,0,.45), inset 0 1px rgba(255,255,255,.05);
  position: relative; transform: translateY(1.5vh);
}
.dossier::after { content: ""; position: absolute; left: 12px; right: 12px; top: 0; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,157,69,.6), transparent); }
.dossier-head { display: flex; align-items: center; justify-content: space-between; padding: 16px 18px 14px; border-bottom: 1px solid var(--line); }
.dossier-head span { font: 500 8px/1 var(--font-mono); letter-spacing: .16em; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.dossier-head i { width: 4px; height: 4px; background: var(--accent); border-radius: 50%; box-shadow: 0 0 7px var(--accent); }
.dossier-head b { font: 500 7px/1 var(--font-mono); letter-spacing: .13em; color: var(--danger); border: 1px solid rgba(255,77,77,.4); padding: 4px 6px; background: rgba(255,77,77,.07); }
.dossier-map { height: clamp(112px, 15vh, 166px); position: relative; overflow: hidden; background: #0a1112; border-bottom: 1px solid var(--line); }
.map-grid { position: absolute; inset: 0; background-image: linear-gradient(rgba(145,192,178,.09) 1px, transparent 1px), linear-gradient(90deg, rgba(145,192,178,.09) 1px, transparent 1px); background-size: 22px 22px; transform: perspective(300px) rotateX(18deg) scale(1.15); opacity: .8; }
.map-lines { position: absolute; inset: 0; width: 100%; height: 100%; }
.map-scan { position: absolute; inset: 0; background: linear-gradient(180deg, transparent 20%, rgba(150,229,207,.12) 50%, transparent 80%); animation: mapScan 4.5s linear infinite; }
@keyframes mapScan { from { transform: translateY(-110%); } to { transform: translateY(110%); } }
.map-tag { position: absolute; font: 500 6.5px/1 var(--font-mono); letter-spacing: .13em; color: var(--teal); padding: 3px 5px; border: 1px solid rgba(150,229,207,.3); background: rgba(8,18,17,.82); }
.tag-a { left: 18%; top: 37%; }
.tag-b { left: 60%; top: 44%; color: #d9e4df; border-color: rgba(255,255,255,.25); }
.map-coord { position: absolute; right: 11px; bottom: 9px; text-align: right; font: 400 6.5px/1.6 var(--font-mono); color: rgba(220,232,225,.42); letter-spacing: .05em; }
.dossier-body { padding: 11px 17px 5px; }
.objective-row { display: flex; align-items: center; gap: 11px; padding: 9px 0; border-bottom: 1px solid rgba(231,240,235,.07); }
.objective-row:last-child { border: 0; }
.objective-row > span { font: 500 8px/1 var(--font-mono); color: var(--dim); }
.objective-row > div { flex: 1; display: flex; flex-direction: column; gap: 3px; }
.objective-row b { font-size: 10.5px; letter-spacing: .11em; font-weight: 600; color: rgba(238,242,236,.8); }
.objective-row small { font: 400 7px/1 var(--font-mono); color: var(--dim); letter-spacing: .04em; }
.objective-row i { width: 13px; height: 13px; border: 1px solid rgba(255,255,255,.24); position: relative; flex: none; }
.objective-row i.done { border-color: rgba(150,229,207,.45); background: rgba(150,229,207,.08); }
.objective-row i.done::after { content: ""; position: absolute; width: 7px; height: 4px; border-left: 1px solid var(--teal); border-bottom: 1px solid var(--teal); transform: rotate(-45deg); left: 2px; top: 2px; }
.dossier-foot { display: flex; align-items: center; justify-content: space-between; padding: 12px 17px; border-top: 1px solid var(--line); background: rgba(255,255,255,.018); }
.dossier-foot > span { font: 500 7px/1 var(--font-mono); color: var(--dim); letter-spacing: .14em; }
.dossier-foot b { display: flex; align-items: center; gap: 3px; color: var(--danger); font: 600 8px/1 var(--font-mono); letter-spacing: .12em; }
.dossier-foot em { width: 13px; height: 3px; display: block; background: var(--danger); }
.dossier-foot em.off { background: rgba(255,255,255,.14); }

.menu-footer { flex: none; border-top: 1px solid var(--line); min-height: 56px; display: flex; align-items: center; justify-content: space-between; position: relative; z-index: 2; }
.control-legend { display: flex; align-items: center; gap: 24px; }
.legend-title { font: 500 7px/1 var(--font-mono); letter-spacing: .16em; color: var(--accent); padding-right: 22px; border-right: 1px solid var(--line); }
.control-legend > div { display: flex; align-items: center; gap: 4px; }
.control-legend small { font: 500 6.5px/1 var(--font-mono); letter-spacing: .13em; color: var(--dim); margin-left: 4px; }
kbd { display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 4px; font: 500 8px/1 var(--font-mono); color: rgba(238,242,236,.72); border: 1px solid rgba(231,240,235,.22); background: rgba(255,255,255,.035); }
kbd.wide { min-width: 37px; }
.build-tag { display: flex; align-items: center; gap: 10px; font: 500 6.5px/1 var(--font-mono); color: var(--dim); letter-spacing: .12em; }
.build-tag i { width: 2px; height: 2px; border-radius: 50%; background: var(--dim); }
.build-tag b { color: rgba(238,242,236,.35); margin-left: 9px; font-weight: 400; }

/* ============ MODAL ============ */
.modal-shell {
  position: absolute; inset: 0; z-index: 60; display: grid; place-items: center; padding: 24px;
  background: rgba(3,5,6,.7); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
}
.brief-card, .pause-card, .result-card {
  width: min(600px, 94vw); max-height: 92dvh; overflow: auto; position: relative;
  background: linear-gradient(145deg, rgba(18,25,26,.98), rgba(7,10,11,.98));
  border: 1px solid rgba(231,240,235,.23); padding: clamp(26px, 4vw, 44px);
  box-shadow: 0 40px 160px rgba(0,0,0,.75), inset 0 1px rgba(255,255,255,.07);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}
.brief-card::before, .pause-card::before, .result-card::before {
  content: ""; position: absolute; left: 0; top: 0; width: 3px; height: 100%;
  background: linear-gradient(180deg, var(--accent), transparent 70%);
}
.close-btn { position: absolute; right: 16px; top: 11px; background: none; border: 0; color: var(--muted); font: 300 30px/1 var(--font-display); cursor: pointer; }
.close-btn:hover { color: var(--accent); }
.brief-kicker { font: 500 8px/1 var(--font-mono); letter-spacing: .18em; color: var(--accent); margin-bottom: 13px; }
.brief-card h2, .pause-card h2, .result-card h2 { margin: 0 0 15px; font-size: clamp(35px, 5.2vw, 57px); line-height: .94; letter-spacing: .035em; font-weight: 600; }
.brief-card h2 span, .pause-card h2 span, .result-card h2 span { color: var(--accent); }
.brief-card > p, .result-card > p { margin: 0 0 22px; color: rgba(230,237,232,.6); font-size: 13px; line-height: 1.7; letter-spacing: .02em; }
.brief-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); margin-bottom: 18px; }
.brief-grid > div { background: #0d1314; padding: 13px; display: flex; flex-direction: column; gap: 5px; }
.brief-grid small { font: 500 6.5px/1 var(--font-mono); color: var(--accent); letter-spacing: .15em; }
.brief-grid b { font-size: 12px; letter-spacing: .06em; font-weight: 600; }
.brief-grid span { font: 400 8px/1.4 var(--font-mono); color: var(--dim); }
.brief-controls { display: flex; flex-wrap: wrap; gap: 13px; padding: 12px 0 20px; border-top: 1px solid var(--line); margin-top: 2px; }
.brief-controls span { font: 500 7.5px/1 var(--font-mono); letter-spacing: .1em; color: var(--muted); display: flex; align-items: center; gap: 5px; }
.brief-controls kbd { color: var(--accent); border-color: rgba(255,157,69,.28); }
.primary-btn.thin { width: 100%; height: 57px; min-width: 0; }
.text-btn { display: block; width: 100%; background: none; border: 0; padding: 13px; font: 500 9px/1 var(--font-mono); letter-spacing: .14em; color: rgba(238,242,236,.7); cursor: pointer; }
.text-btn:hover { color: var(--accent); }
.text-btn.muted { color: var(--dim); }
.pause-card { width: min(460px, 92vw); }
.pause-sub { margin: 0 0 24px; color: var(--muted); font: 400 11px/1.5 var(--font-mono); letter-spacing: .04em; }
.pause-stats, .result-stats { display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--line); margin-bottom: 22px; }
.pause-stats > div, .result-stats > div { padding: 14px; border-right: 1px solid var(--line); display: flex; flex-direction: column; gap: 6px; }
.pause-stats > div:last-child, .result-stats > div:last-child { border: 0; }
.pause-stats small, .result-stats small { font: 500 6.5px/1 var(--font-mono); letter-spacing: .14em; color: var(--dim); }
.pause-stats b, .result-stats b { font-size: 20px; letter-spacing: .06em; font-weight: 600; color: var(--ink); }
.result-card { width: min(660px, 94vw); text-align: center; }
.result-kicker { display: inline-block; font: 500 8px/1 var(--font-mono); letter-spacing: .22em; color: var(--teal); border: 1px solid rgba(150,229,207,.3); padding: 8px 15px; margin-bottom: 18px; background: rgba(150,229,207,.06); }
.result-card > p { max-width: 430px; margin-left: auto; margin-right: auto; }
.result-stats { grid-template-columns: repeat(4, 1fr); }
.result-card.failed .result-kicker { color: var(--danger); border-color: rgba(255,77,77,.3); background: rgba(255,77,77,.06); }
.result-card.failed h2 span { color: var(--danger); }
.rank-line { display: flex; align-items: center; justify-content: center; gap: 16px; border-top: 1px solid var(--line); padding: 18px 0; margin-bottom: 20px; }
.rank-line > span { font: 500 7px/1 var(--font-mono); letter-spacing: .16em; color: var(--dim); }
.rank-line > b { font: 700 38px/1 var(--font-display); color: var(--accent); text-shadow: 0 0 24px rgba(255,157,69,.5); }
#rank-stars { color: var(--accent); font-size: 13px; letter-spacing: .28em; }
.result-actions { display: grid; grid-template-columns: 1fr 150px; gap: 10px; }
.result-actions .primary-btn { margin: 0; }

/* ============ HUD ============ */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top { position: absolute; top: max(18px, env(safe-area-inset-top)); left: max(20px, env(safe-area-inset-left)); right: max(20px, env(safe-area-inset-right)); display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.objective-panel {
  position: relative; width: min(325px, 30vw); padding: 12px 16px;
  background: linear-gradient(135deg, rgba(8,12,13,.8), rgba(8,12,13,.42));
  border-left: 2px solid var(--accent); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.panel-cut { position: absolute; inset: 0; border: 1px solid rgba(231,240,235,.11); border-left: 0; pointer-events: none; }
.obj-head { display: flex; align-items: center; gap: 7px; font: 500 6.5px/1 var(--font-mono); letter-spacing: .13em; color: var(--muted); }
.obj-head b { margin-left: auto; color: rgba(238,242,236,.7); font-weight: 500; }
.live-dot { width: 4px; height: 4px; background: var(--danger); border-radius: 50%; box-shadow: 0 0 8px var(--danger); animation: blink 1.2s infinite; }
@keyframes blink { 50% { opacity: .25; } }
.obj-title { font-size: 16px; font-weight: 600; letter-spacing: .12em; margin: 7px 0 8px; }
.obj-progress { height: 2px; background: rgba(255,255,255,.11); overflow: hidden; }
.obj-progress > div { height: 100%; width: 0%; background: linear-gradient(90deg, var(--accent), #ffd08e); box-shadow: 0 0 8px rgba(255,157,69,.6); transition: width .4s; }
.obj-sub { display: flex; justify-content: space-between; margin-top: 6px; font: 500 6.5px/1 var(--font-mono); letter-spacing: .08em; color: var(--dim); }
.obj-sub span:last-child { color: var(--accent); }

.score-cluster { display: flex; align-items: center; gap: 18px; height: 44px; }
.wave-pips { display: flex; gap: 4px; }
.wave-pips i { width: 19px; height: 3px; background: rgba(255,255,255,.15); display: block; }
.wave-pips i.active { background: var(--accent); box-shadow: 0 0 8px rgba(255,157,69,.6); }
.wave-pips i.complete { background: rgba(150,229,207,.75); }
.score-value { display: flex; flex-direction: column; gap: 3px; }
.score-value small { font: 500 6px/1 var(--font-mono); letter-spacing: .18em; color: var(--dim); }
.score-value b { font: 600 16px/1 var(--font-mono); letter-spacing: .08em; color: #eef2ec; }
.combo { font: 600 10px/1 var(--font-mono); color: var(--accent); padding: 5px 7px; border: 1px solid rgba(255,157,69,.28); background: rgba(255,157,69,.07); opacity: 0; transform: scale(.8); transition: .2s; }
.combo.show { opacity: 1; transform: scale(1); }

.hud-right { display: flex; align-items: flex-start; gap: 10px; }
.minimap-wrap { width: clamp(104px, 10vw, 144px); height: clamp(104px, 10vw, 144px); position: relative; }
#minimap { position: absolute; inset: 0; width: 100%; height: 100%; border-radius: 50%; background: rgba(8,15,15,.75); }
.minimap-ring { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(150,229,207,.28); box-shadow: 0 0 0 5px rgba(7,12,13,.45), 0 0 0 6px rgba(150,229,207,.08); pointer-events: none; }
.minimap-label { position: absolute; bottom: -14px; left: 50%; transform: translateX(-50%); font: 500 5.5px/1 var(--font-mono); letter-spacing: .17em; color: rgba(150,229,207,.55); white-space: nowrap; }
.minimap-n { position: absolute; top: 5px; left: 50%; transform: translateX(-50%); font: 500 6px/1 var(--font-mono); color: var(--teal); }
.hud-buttons { display: flex; flex-direction: column; gap: 6px; }
.hud-icon { width: 31px; height: 31px; border: 1px solid rgba(231,240,235,.15); background: rgba(8,12,13,.55); display: grid; place-items: center; color: var(--muted); cursor: pointer; pointer-events: auto; }
.hud-icon:hover { color: var(--accent); border-color: rgba(255,157,69,.4); }
.hud-icon svg { width: 14px; height: 14px; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 0; height: 0; --spread: 12px; }
.crosshair > i { position: absolute; background: rgba(240,246,241,.88); box-shadow: 0 0 3px rgba(0,0,0,.9); }
.ch-top { width: 1px; height: 7px; left: 0; top: calc(-1 * var(--spread) - 7px); }
.ch-bottom { width: 1px; height: 7px; left: 0; top: var(--spread); }
.ch-left { width: 7px; height: 1px; top: 0; left: calc(-1 * var(--spread) - 7px); }
.ch-right { width: 7px; height: 1px; top: 0; left: var(--spread); }
.crosshair > b { position: absolute; width: 2px; height: 2px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 5px var(--accent); left: -1px; top: -1px; }
.hitmarker { position: absolute; left: 50%; top: 50%; width: 28px; height: 28px; transform: translate(-50%,-50%) rotate(45deg); opacity: 0; }
.hitmarker i { position: absolute; background: #fff; box-shadow: 0 0 4px rgba(255,255,255,.8); }
.hitmarker i:nth-child(1) { width: 8px; height: 1px; left: 0; top: 0; }
.hitmarker i:nth-child(2) { width: 8px; height: 1px; right: 0; top: 0; }
.hitmarker i:nth-child(3) { width: 8px; height: 1px; left: 0; bottom: 0; }
.hitmarker i:nth-child(4) { width: 8px; height: 1px; right: 0; bottom: 0; }
.hitmarker.kill i { background: var(--danger); box-shadow: 0 0 5px var(--danger); }
.hitmarker.head i { background: var(--accent); box-shadow: 0 0 5px var(--accent); }

.wave-banner {
  position: absolute; left: 50%; top: 23%; transform: translate(-50%,-50%); display: flex; flex-direction: column;
  align-items: center; gap: 7px; opacity: 0; pointer-events: none; transition: opacity .5s, transform .5s;
  text-align: center; width: min(480px, 80vw);
}
.wave-banner.show { opacity: 1; transform: translate(-50%,-50%) scale(1); }
.wave-banner small { font: 500 8px/1 var(--font-mono); letter-spacing: .38em; color: var(--accent); }
.wave-banner b { font-size: clamp(42px, 7vw, 76px); line-height: .9; letter-spacing: .08em; font-weight: 600; text-shadow: 0 8px 40px rgba(0,0,0,.7); }
.wave-banner span { font: 500 7.5px/1.4 var(--font-mono); letter-spacing: .18em; color: rgba(238,242,236,.6); }
.wb-line { width: 100%; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,157,69,.55), transparent); margin: 4px 0; }

.hud-bottom { position: absolute; left: max(20px, env(safe-area-inset-left)); right: max(20px, env(safe-area-inset-right)); bottom: max(18px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; justify-content: space-between; }
.glass { background: linear-gradient(140deg, rgba(8,13,14,.78), rgba(8,13,14,.35)); border: 1px solid rgba(231,240,235,.13); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); }
.vitals-panel { width: 243px; padding: 12px 14px; position: relative; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%); }
.operator-chip { display: flex; align-items: center; gap: 8px; padding-bottom: 9px; border-bottom: 1px solid rgba(231,240,235,.1); margin-bottom: 9px; }
.operator-chip > span { width: 26px; height: 26px; display: grid; place-items: center; font: 600 9px/1 var(--font-mono); color: var(--accent); border: 1px solid rgba(255,157,69,.4); background: rgba(255,157,69,.09); }
.operator-chip > div { display: flex; flex-direction: column; gap: 3px; }
.operator-chip small { font: 500 5.5px/1 var(--font-mono); color: var(--dim); letter-spacing: .16em; }
.operator-chip b { font-size: 10px; letter-spacing: .15em; font-weight: 600; }
.operator-chip .online { margin-left: auto; width: 5px; height: 5px; background: var(--teal); border-radius: 50%; box-shadow: 0 0 6px var(--teal); }
.vital-row { display: flex; align-items: center; gap: 8px; margin-top: 7px; }
.vital-row > svg { width: 15px; height: 15px; color: var(--accent); flex: none; }
.vital-row.armor > svg { color: #7db5dc; }
.vital-row > div { flex: 1; display: flex; flex-direction: column; gap: 4px; }
.vital-row span { display: flex; justify-content: space-between; font: 500 6px/1 var(--font-mono); letter-spacing: .12em; color: var(--muted); }
.vital-row span b { color: rgba(238,242,236,.9); font-weight: 500; font-size: 7px; }
.bar { height: 3px; background: rgba(255,255,255,.1); overflow: hidden; }
.bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #f47e35, var(--accent)); transition: width .25s; box-shadow: 0 0 7px rgba(255,157,69,.4); }
.armor .bar i { background: linear-gradient(90deg, #4e8eb9, #8bc7eb); box-shadow: 0 0 7px rgba(125,181,220,.3); }
.vitals-spike { position: absolute; right: 0; bottom: 0; width: 14px; height: 14px; background: linear-gradient(135deg, transparent 50%, rgba(255,157,69,.25) 50%); }

.weapon-panel { width: 226px; padding: 11px 14px 10px; position: relative; clip-path: polygon(0 0, 100% 0, 100% 100%, 13px 100%, 0 calc(100% - 13px)); }
.weapon-top { display: flex; justify-content: space-between; align-items: center; }
.weapon-class { font: 500 5.5px/1 var(--font-mono); letter-spacing: .13em; color: var(--dim); }
.fire-mode { font: 500 5.5px/1 var(--font-mono); letter-spacing: .1em; color: var(--accent); display: flex; align-items: center; gap: 4px; }
.fire-mode i { width: 3px; height: 3px; background: var(--accent); border-radius: 50%; }
.weapon-name { font-size: 25px; line-height: 1; letter-spacing: .06em; font-weight: 600; margin: 5px 0 2px; }
.weapon-name span { color: var(--accent); }
.ammo-row { display: flex; align-items: flex-end; justify-content: space-between; }
.ammo { display: flex; align-items: baseline; gap: 5px; }
.ammo b { font: 500 33px/.9 var(--font-mono); letter-spacing: -.07em; color: #f0f4ef; }
.ammo span { font: 400 10px/1 var(--font-mono); color: var(--dim); }
.ammo span em { font-style: normal; }
.reload-viz { width: 34px; height: 34px; position: relative; display: grid; place-items: center; }
.reload-viz svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.reload-viz circle { fill: none; stroke-width: 2; }
.ring-bg { stroke: rgba(255,255,255,.12); }
.ring-fill { stroke: var(--accent); stroke-dasharray: 126; stroke-dashoffset: 126; transition: stroke-dashoffset .05s linear; }
.reload-viz span { font: 500 7px/1 var(--font-mono); color: var(--muted); }
.ammo-ticks { display: flex; gap: 2px; margin-top: 7px; height: 3px; }
.ammo-ticks i { flex: 1; background: rgba(255,157,69,.7); }
.ammo-ticks i.empty { background: rgba(255,255,255,.1); }
.low-ammo { position: absolute; bottom: 113px; right: 24px; font: 500 7px/1 var(--font-mono); letter-spacing: .15em; color: var(--danger); opacity: 0; transition: .2s; }
.low-ammo.show { opacity: 1; animation: blink 1s infinite; }
.low-ammo b { border: 1px solid rgba(255,77,77,.5); padding: 3px 5px; margin-left: 4px; }

.kill-feed { position: absolute; right: max(24px, env(safe-area-inset-right)); top: calc(max(18px, env(safe-area-inset-top)) + clamp(122px, 12vw, 172px)); display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.kill-row { display: flex; align-items: center; gap: 7px; padding: 6px 9px; background: rgba(8,12,13,.68); border-right: 2px solid var(--accent); font: 500 7px/1 var(--font-mono); letter-spacing: .06em; color: rgba(238,242,236,.72); animation: killIn .25s ease-out; }
.kill-row b { color: var(--accent); font-weight: 500; }
.kill-row .skull { color: var(--danger); }
@keyframes killIn { from { opacity: 0; transform: translateX(12px); } }
.pickup-toast { position: absolute; left: 50%; top: 58%; transform: translate(-50%, -8px); display: flex; flex-direction: column; align-items: center; gap: 5px; opacity: 0; transition: .3s; }
.pickup-toast.show { opacity: 1; transform: translate(-50%, 0); }
.pickup-toast b { font: 500 8px/1 var(--font-mono); letter-spacing: .2em; color: var(--teal); }
.pickup-toast span { font: 600 15px/1 var(--font-display); letter-spacing: .08em; color: #dffcf4; }
#hit-flash { position: absolute; inset: 0; background: rgba(255,255,255,.08); opacity: 0; pointer-events: none; }
.tracer-flash { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 42%, rgba(255,196,109,.14), transparent 45%); opacity: 0; }

/* mobile controls */
.mobile-ui { display: none; position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: max(19px, env(safe-area-inset-left)); bottom: max(35px, env(safe-area-inset-bottom));
  width: 126px; height: 126px; border-radius: 50%; pointer-events: auto; touch-action: none;
  border: 1px solid rgba(231,240,235,.18); background: radial-gradient(circle, rgba(255,255,255,.035), rgba(6,11,12,.3));
  box-shadow: inset 0 0 30px rgba(0,0,0,.3);
}
.js-ring { position: absolute; inset: 15px; border: 1px dashed rgba(231,240,235,.16); border-radius: 50%; }
.js-knob { position: absolute; width: 52px; height: 52px; left: 50%; top: 50%; margin: -26px 0 0 -26px; border-radius: 50%; border: 1px solid rgba(255,157,69,.6); background: radial-gradient(circle at 35% 30%, rgba(255,157,69,.38), rgba(43,27,15,.75)); box-shadow: 0 0 22px rgba(255,157,69,.2); transition: transform .05s; }
.joystick > span { position: absolute; bottom: -18px; left: 50%; transform: translateX(-50%); font: 500 6px/1 var(--font-mono); letter-spacing: .2em; color: rgba(255,255,255,.35); }
.look-zone { position: absolute; right: 12%; top: 20%; width: 52%; height: 55%; pointer-events: auto; touch-action: none; }
.look-zone > span { position: absolute; right: 3%; top: 50%; font: 500 5.5px/1 var(--font-mono); color: rgba(255,255,255,.12); letter-spacing: .17em; transform: rotate(90deg); }
.fire-btn {
  position: absolute; right: max(28px, env(safe-area-inset-right)); bottom: max(35px, env(safe-area-inset-bottom));
  width: 94px; height: 94px; border-radius: 50%; border: 1px solid rgba(255,157,69,.45); background: radial-gradient(circle, rgba(255,157,69,.2), rgba(12,16,17,.55) 70%);
  color: var(--accent); pointer-events: auto; touch-action: none; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; padding: 0;
}
.fire-btn svg { width: 35px; height: 35px; }
.fire-btn b { font: 600 6px/1 var(--font-mono); letter-spacing: .18em; }
.fire-ring { position: absolute; inset: 8px; border: 1px solid rgba(255,157,69,.16); border-radius: 50%; }
.fire-btn:active { background: radial-gradient(circle, rgba(255,102,32,.5), rgba(12,16,17,.5) 70%); transform: scale(.96); }
.round-btn {
  position: absolute; right: max(137px, calc(env(safe-area-inset-right) + 109px)); bottom: max(92px, calc(env(safe-area-inset-bottom) + 57px));
  width: 51px; height: 51px; border-radius: 50%; border: 1px solid rgba(231,240,235,.2); background: rgba(8,12,13,.5);
  color: rgba(238,242,236,.7); pointer-events: auto; touch-action: none; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; padding: 0;
}
.round-btn svg { width: 17px; height: 17px; }
.round-btn span { font: 500 5px/1 var(--font-mono); letter-spacing: .1em; color: rgba(255,255,255,.4); }
.round-btn.small { width: 42px; height: 42px; right: max(100px, calc(env(safe-area-inset-right) + 72px)); bottom: max(28px, env(safe-area-inset-bottom)); }
.round-btn.small + .round-btn.small { right: max(150px, calc(env(safe-area-inset-right) + 122px)); bottom: max(24px, calc(env(safe-area-inset-bottom) + 4px)); }
.round-btn:active { background: rgba(255,157,69,.2); color: var(--accent); }

.fade { position: absolute; inset: 0; z-index: 90; background: #050808; pointer-events: none; opacity: 0; transition: opacity .48s ease; }
.fade.on { opacity: 1; }
.rotate-hint {
  display: none; position: absolute; inset: 0; z-index: 100; background: #070a0c; color: var(--ink);
  flex-direction: column; align-items: center; justify-content: center; gap: 12px; text-align: center;
}
.rotate-hint svg { width: 54px; height: 54px; color: var(--accent); animation: rotateHint 2.4s infinite ease-in-out; }
.rotate-hint b { font: 600 13px/1 var(--font-mono); letter-spacing: .18em; color: var(--accent); }
.rotate-hint span { font: 400 9px/1 var(--font-mono); color: var(--muted); letter-spacing: .1em; }
@keyframes rotateHint { 0%, 20% { transform: rotate(0); } 60%, 80% { transform: rotate(90deg); } 100% { transform: rotate(0); } }
.boot-error { position: absolute; inset: 0; z-index: 110; background: #080b0c; color: #ff9d45; font: 12px/1.6 var(--font-mono); padding: 40px; white-space: pre-wrap; }

/* ============ RESPONSIVE ============ */
@media (max-width: 1050px) {
  .dossier { width: 300px; }
  .hero-copy { width: 57vw; }
  .menu-meta > div { padding-right: 18px; margin-right: 18px; }
  .control-legend { gap: 15px; }
  .legend-title { padding-right: 15px; }
  .build-tag span:nth-of-type(3), .build-tag i:nth-of-type(2) { display: none; }
}
@media (max-width: 820px), (max-height: 560px) {
  .menu-shell { padding: max(13px, env(safe-area-inset-top)) max(17px, env(safe-area-inset-left)) max(10px, env(safe-area-inset-bottom)); }
  .topbar { height: 47px; }
  .brand-mark { width: 27px; height: 27px; }
  .brand-copy b { font-size: 14px; }
  .brand-copy small { font-size: 6px; }
  .net-status { display: none; }
  .menu-main { padding: 1vh 0; }
  .dossier { display: none; }
  .hero-copy { width: 100%; max-width: 470px; padding-left: 0; }
  .hero-copy h1 { font-size: clamp(64px, 16vw, 98px); }
  .hero-sub b { font-size: 17px; }
  .mission-copy { margin: 16px 0 20px; font-size: 11px; }
  .hero-actions { gap: 8px; }
  .primary-btn { height: 56px; min-width: 210px; padding-left: 12px; }
  .btn-copy b { font-size: 17px; }
  .btn-copy small { font-size: 6px; }
  .ghost-btn { height: 56px; min-width: 107px; padding: 0 12px; font-size: 8px; }
  .ghost-btn svg { display: none; }
  .menu-meta { margin-top: 18px; }
  .menu-meta > div { padding: 9px 14px 0 0; margin-right: 14px; }
  .menu-meta b { font-size: 9px; }
  .menu-meta small { font-size: 6px; }
  .control-legend { display: none; }
  .menu-footer { min-height: 38px; }
  .build-tag { margin-left: auto; }
  .build-tag b { display: none; }
  .score-cluster { gap: 10px; }
  .objective-panel { width: 265px; }
  .hud-bottom { bottom: max(14px, env(safe-area-inset-bottom)); }
}
@media (pointer: coarse) {
  .mobile-ui { display: block; }
  .control-legend { display: none; }
  .hud-bottom { bottom: max(18px, env(safe-area-inset-bottom)); }
  .vitals-panel { width: 172px; padding: 9px 10px; position: absolute; left: max(155px, calc(env(safe-area-inset-left) + 134px)); bottom: 0; }
  .weapon-panel { width: 164px; padding: 8px 10px; position: absolute; right: 0; bottom: 0; }
  .operator-chip { display: none; }
  .weapon-name { font-size: 19px; }
  .ammo b { font-size: 27px; }
  .weapon-class { display: none; }
  .low-ammo { bottom: 94px; right: 17px; }
  .objective-panel { width: 244px; }
  .obj-title { font-size: 13px; }
  .hud-top { top: max(10px, env(safe-area-inset-top)); left: max(10px, env(safe-area-inset-left)); right: max(10px, env(safe-area-inset-right)); }
  .look-zone { display: block; }
}
@media (max-width: 620px) {
  .hero-copy h1 { font-size: clamp(58px, 18vw, 88px); }
  .hero-sub { margin-top: 7px; gap: 9px; }
  .hero-sub b { font-size: 14px; letter-spacing: .32em; padding-left: 8px; }
  .hero-sub span { font-size: 6px; }
  .mission-copy { font-size: 9.5px; margin: 12px 0 15px; }
  .eyebrow { font-size: 7.5px; margin-bottom: 8px; }
  .eyebrow-line { width: 22px; }
  .primary-btn { min-width: 194px; height: 51px; }
  .btn-icon { width: 26px; height: 26px; }
  .btn-copy b { font-size: 15.5px; }
  .ghost-btn { height: 51px; min-width: 95px; font-size: 7px; }
  .menu-meta { display: none; }
  .menu-footer { min-height: 30px; }
  .build-tag { font-size: 5.5px; }
  .objective-panel { width: 202px; padding: 9px 11px; }
  .obj-title { font-size: 11px; margin: 5px 0 6px; }
  .obj-head { font-size: 5.5px; }
  .obj-sub { font-size: 5.5px; }
  .obj-sub span:last-child { display: none; }
  .score-cluster { gap: 7px; height: 35px; }
  .score-value b { font-size: 13px; }
  .wave-pips i { width: 13px; }
  .minimap-wrap { width: 82px; height: 82px; }
  .hud-buttons { gap: 4px; }
  .hud-icon { width: 27px; height: 27px; }
  .vitals-panel { left: max(130px, calc(env(safe-area-inset-left) + 112px)); width: 148px; }
  .weapon-panel { width: 142px; }
  .ammo b { font-size: 24px; }
  .brief-grid { grid-template-columns: 1fr; }
  .brief-grid span { display: none; }
  .result-stats { grid-template-columns: repeat(2, 1fr); }
  .result-stats > div:nth-child(2) { border-right: 0; }
  .result-stats > div:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  .result-actions { grid-template-columns: 1fr; }
  .result-actions .ghost-btn { height: 46px; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .topbar { height: 39px; }
  .menu-shell { padding-top: max(8px, env(safe-area-inset-top)); }
  .hero-copy h1 { font-size: clamp(48px, 14vh, 74px); }
  .eyebrow { margin-bottom: 5px; }
  .hero-sub { margin-top: 5px; }
  .mission-copy { display: none; }
  .hero-actions { margin-top: 12px; }
  .primary-btn, .ghost-btn { height: 48px; }
  .menu-meta { display: none; }
  .menu-footer { min-height: 29px; }
  .joystick { width: 106px; height: 106px; bottom: 26px; }
  .js-knob { width: 46px; height: 46px; margin: -23px 0 0 -23px; }
  .fire-btn { width: 78px; height: 78px; bottom: 26px; }
  .round-btn { width: 45px; height: 45px; bottom: 75px; }
  .round-btn.small { width: 39px; height: 39px; bottom: 25px; }
  .round-btn.small + .round-btn.small { bottom: 20px; }
  .vitals-panel { width: 150px; }
  .weapon-panel { width: 150px; }
  .wave-banner { top: 26%; }
  .hud-top { top: 8px; }
}
@media (orientation: portrait) and (max-width: 600px) {
  #rotate-hint { display: none; }
}
@media (orientation: portrait) and (max-height: 700px) and (pointer: coarse) {
  .rotate-hint { display: flex; }
}

import * as THREE from 'three';
import '@fontsource/rajdhani/500.css';
import '@fontsource/rajdhani/600.css';
import '@fontsource/rajdhani/700.css';
import '@fontsource/ibm-plex-mono/400.css';
import '@fontsource/ibm-plex-mono/500.css';
import './style.css';

const $ = (id) => document.getElementById(id);
const ui = {
  menu: $('main-menu'), briefing: $('briefing'), hud: $('hud'), pause: $('pause-menu'), result: $('result-screen'),
  canvas: $('game-canvas'), fade: $('fade'), error: $('boot-error'),
};
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const rand = (a, b) => a + Math.random() * (b - a);
const choose = (a) => a[Math.floor(Math.random() * a.length)];
const isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
if (isTouch) $('input-label').textContent = 'TACTILE CONTROLS';

let renderer, scene, camera, clock;
let active = false, paused = false, gameOver = false, audioOn = true;
let player, gun, muzzleFlash, cameraBob = 0, weaponKick = 0, walkPhase = 0;
let yaw = 0, pitch = 0, moveX = 0, moveZ = 0, isSprinting = false, isCrouching = false, jumping = false;
let health = 100, armor = 50, ammo = 30, reserve = 120, score = 0, kills = 0, shots = 0, hits = 0;
let wave = 0, waveKills = 0, waveTotal = 0, startTime = 0, elapsed = 0, lastShot = 0, reloadStart = 0, reloadDuration = 1.65;
let enemies = [], bullets = [], effects = [], pickups = [], colliders = [], decor = [], audioCtx = null;
let hitTimer = 0, hurtTimer = 0, comboCount = 0, comboTime = 0, lastKillTime = 0, waveBannerTimer = 0;
let joystickPointer = null, lookPointer = null, fireHeld = false, lastLookX = 0, lastLookY = 0;
let playerVelocity = new THREE.Vector3(), moveVelocity = new THREE.Vector3(), tmpVec = new THREE.Vector3();
const raycaster = new THREE.Raycaster();
const worldSize = 44;

function boot() {
  try {
    renderer = new THREE.WebGLRenderer({ canvas: ui.canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.5 : 2));
    renderer.setSize(innerWidth, innerHeight, false);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x101719);
    scene.fog = new THREE.FogExp2(0x111a1b, 0.018);
    camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 115);
    camera.rotation.order = 'YXZ';
    clock = new THREE.Clock();
    player = new THREE.Group();
    player.position.set(0, 1.68, 11);
    scene.add(player);
    player.add(camera);
    buildWorld();
    buildWeapon();
    setupEvents();
    updateMinimap();
    window.addEventListener('resize', onResize);
    requestAnimationFrame(loop);
  } catch (e) {
    console.error(e);
    ui.error.textContent = `Unable to initialize the tactical renderer.\n\n${e.message}\n\nTry a browser with WebGL enabled.`;
    ui.error.classList.remove('hidden');
  }
}

const mats = {};
function mat(color, roughness = .8, metalness = .1, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness, ...extra });
}
function box(parent, name, size, pos, material, cast = true, receive = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material);
  mesh.name = name;
  mesh.position.set(...pos);
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  parent.add(mesh);
  return mesh;
}
function cylinder(parent, name, radiusTop, radiusBottom, height, pos, material, segments = 12) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
  mesh.name = name;
  mesh.position.set(...pos);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}
function addCollider(x, z, w, d, h = 2) { colliders.push({ x, z, w, d, h }); }

function buildWorld() {
  mats.floor = mat(0x303638, .91, .16);
  mats.wall = mat(0x343b3c, .9, .18);
  mats.dark = mat(0x141a1b, .65, .35);
  mats.steel = mat(0x4b5352, .48, .55);
  mats.crate = mat(0x4a4b3b, .91, .12);
  mats.crate2 = mat(0x343e3b, .9, .16);
  mats.orange = mat(0xb8672e, .62, .2);
  mats.yellow = mat(0xe4a847, .6, .16, { emissive: 0x4f2607 });
  mats.cyan = mat(0x8bc4b2, .35, .15, { emissive: 0x1b6354, emissiveIntensity: 1.4 });
  mats.red = mat(0x9c3830, .45, .2, { emissive: 0x50100c, emissiveIntensity: 1.2 });
  mats.black = mat(0x090c0d, .7, .3);
  mats.concrete = mat(0x555a56, .96, .03);
  mats.rubble = mat(0x292f30, 1, 0);

  scene.add(new THREE.HemisphereLight(0xbed0c8, 0x141819, 1.35));
  const moon = new THREE.DirectionalLight(0xc9d7d0, 2.0);
  moon.position.set(-12, 24, 10); moon.castShadow = true;
  moon.shadow.mapSize.set(isTouch ? 1024 : 2048, isTouch ? 1024 : 2048);
  moon.shadow.camera.left = -34; moon.shadow.camera.right = 34; moon.shadow.camera.top = 28; moon.shadow.camera.bottom = -28;
  moon.shadow.bias = -0.0004; moon.shadow.normalBias = 0.025; scene.add(moon);
  const fill = new THREE.DirectionalLight(0x82999b, .7); fill.position.set(20, 10, -20); scene.add(fill);
  const skyGlow = new THREE.PointLight(0x315e5c, 28, 38, 1.8); skyGlow.position.set(-1, 9, -17); scene.add(skyGlow);

  const ground = new THREE.Mesh(new THREE.PlaneGeometry(90, 90), mats.floor);
  ground.rotation.x = -Math.PI / 2; ground.position.y = -.12; ground.receiveShadow = true; scene.add(ground);
  // Subtle concrete seams and hazard markings anchor scale and orientation.
  const seamMat = mat(0x242b2c, 1, 0);
  for (let x = -40; x <= 40; x += 5) box(scene, 'floor seam', [.035, .012, 80], [x, -.1, 0], seamMat, false);
  for (let z = -40; z <= 40; z += 5) box(scene, 'floor seam', [80, .012, .035], [0, -.099, z], seamMat, false);

  // Distant perimeter and broken industrial walls.
  box(scene, 'north perimeter', [84, 9, 1], [0, 4.4, -39], mats.wall);
  box(scene, 'west perimeter', [1, 9, 80], [-42, 4.4, 0], mats.wall);
  box(scene, 'east perimeter', [1, 9, 80], [42, 4.4, 0], mats.wall);
  box(scene, 'south left wall', [22, 8, 1], [-31, 4, 38], mats.wall);
  box(scene, 'south right wall', [22, 8, 1], [31, 4, 38], mats.wall);
  for (const x of [-36, -22, 22, 36]) {
    box(scene, 'wall reinforcement', [.24, 8.8, 1.25], [x, 4.3, -38.35], mats.steel);
    box(scene, 'wall light', [.13, .12, .5], [x, 6.7, -37.7], mats.cyan, false);
  }
  box(scene, 'north ledge', [83, .3, 1.6], [0, 8.6, -38.1], mats.dark);
  // Relay building, visible beyond the active arena.
  box(scene, 'relay base', [13, 5, 8], [0, 2.5, -31], mats.dark);
  box(scene, 'relay face', [12.4, 4.3, .18], [0, 2.65, -26.9], mats.steel);
  box(scene, 'relay tower', [3.3, 11, 3.3], [0, 10, -31], mats.wall);
  box(scene, 'tower crown', [5.4, .45, 5.4], [0, 15.5, -31], mats.dark);
  cylinder(scene, 'antenna mast', .1, .14, 8, [0, 19.6, -31], mats.steel, 8);
  for (let y = 16.3; y < 22.8; y += 1.3) {
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(.13, 8, 6), mats.red);
    beacon.position.set(0, y, -31); scene.add(beacon);
  }
  for (let i = 0; i < 5; i++) {
    const x = -4.4 + i * 2.2;
    box(scene, 'relay vent', [1.15, 2.8, .14], [x, 2.3, -26.76], mats.dark);
    box(scene, 'vent glow', [.05, 2.2, .04], [x, 2.3, -26.65], mats.cyan, false);
  }
  box(scene, 'relay sign', [7.6, 1.1, .2], [0, 5.2, -26.78], mats.black);
  box(scene, 'sign text bar', [4.1, .045, .03], [0, 5.35, -26.65], mats.cyan, false);

  // Warehouse wings frame the combat lane.
  buildWarehouse(-29, -23, false);
  buildWarehouse(29, -23, true);

  // Cover: varied crates, barriers, cable spools and drums.
  const crates = [
    [-15,-22,3.8,2.4,2.2], [-10,-28,3,2.8,2.5], [14,-25,4,2.2,2.4], [19,-18,3.1,2.5,2.2],
    [-20,-10,3.5,2.3,2], [-11,-13,4.2,2.3,2.5], [10,-12,4,2.5,2.4], [19,-7,3.2,2.3,2],
    [-16,0,3.8,2.2,1.8], [-7,-2,3.2,2.1,2.1], [8,0,4.2,2.4,2.2], [18,4,3.4,2.2,2.2],
    [-20,12,4,2.2,2.1], [-11,17,3.2,2,1.8], [10,14,4,2.2,2], [19,18,3.2,2.2,2.1],
    [-5,-20,2.1,2.1,2.5], [5,-19,2.4,2.1,2.7], [-2,9,2.2,2.2,2.4], [3,20,2.3,2,2.2],
  ];
  crates.forEach(([x,z,w,d,h], i) => buildCrate(x,z,w,d,h,i % 3 === 0 ? mats.crate2 : mats.crate));
  for (const [x,z] of [[-25,-14], [24,-28], [-24,5], [26,10], [-4,-33], [5,28]]) buildBarrier(x,z,rand(3.2,4.8));
  for (const [x,z] of [[-25,-6], [25,-3], [-25,23], [25,25], [-17,-31], [17,-31]]) buildDrum(x,z);

  // Scattered broken masonry and metal debris.
  for (let i = 0; i < 46; i++) {
    const x = rand(-37, 37), z = rand(-35, 33);
    if (Math.abs(x) < 22 && Math.abs(z) < 8) continue;
    const size = rand(.18, .75);
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(size, 0), i % 2 ? mats.rubble : mats.concrete);
    rock.position.set(x, size * .42, z); rock.rotation.set(rand(0, 2), rand(0, 6), rand(0, 2)); rock.castShadow = true; rock.receiveShadow = true; scene.add(rock);
  }

  // Scattered industrial lamps and emissive safety strips.
  for (const [x,z] of [[-26,-11],[26,-11],[-26,19],[26,19],[0,-36]]) {
    cylinder(scene, 'lamp post', .11, .16, 5.6, [x, 2.8, z], mats.dark, 8);
    box(scene, 'lamp arm', [1.2,.12,.12], [x + (x < 0 ? .45 : -.45),5.45,z], mats.steel);
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(.8,.12,.5), mats.yellow);
    lamp.position.set(x + (x < 0 ? .82 : -.82),5.35,z); scene.add(lamp);
    const pl = new THREE.PointLight(0xffa750, 8, 11, 2); pl.position.set(lamp.position.x, 5, z); scene.add(pl);
  }
  // Broken power lines and industrial pipework.
  for (const side of [-1, 1]) {
    for (let z = -34; z <= 31; z += 9) {
      box(scene, 'pipe', [.32,.32,7.8], [side * 39, 2.6, z], mats.dark);
      cylinder(scene, 'pipe collar', .29, .29, .22, [side * 39, 2.6, z - 3.4], mats.steel, 10).rotation.x = Math.PI / 2;
    }
  }
  buildConsole(-2.2, -25.8);
  buildConsole(2.2, -25.8);
  addCollider(-29, -23, 12, 11, 8); addCollider(29, -23, 12, 11, 8);
  addCollider(0, -31, 13, 8, 5);
  for (const [x,z,w,d,h] of crates) addCollider(x,z,w,d,h);
  for (const [x,z] of [[-25,-14],[24,-28],[-24,5],[26,10],[-4,-33],[5,28]]) addCollider(x,z,4.2,.9,1.2);
}

function buildWarehouse(x, z, mirror) {
  const wall = mats.wall, dark = mats.dark;
  box(scene, 'warehouse body', [13, 7, 12], [x, 3.5, z], wall);
  box(scene, 'warehouse roof', [14, .45, 13], [x, 7.1, z], dark);
  const frontZ = z + 6.08;
  box(scene, 'warehouse opening shadow', [8, 4.9, .15], [x, 2.9, frontZ], mats.black);
  for (let dx of [-5.5, 5.5]) box(scene, 'warehouse upright', [.5, 6.8, .6], [x+dx,3.4,frontZ], mats.steel);
  box(scene, 'warehouse lintel', [11.5,.45,.6], [x,6.6,frontZ], mats.steel);
  for (let i=0;i<5;i++) {
    const xx = x - 3.2 + i*1.6;
    box(scene,'warehouse slat',[.09,4,.1],[xx,2.8,frontZ+.08],mats.dark);
  }
  box(scene, 'warehouse sign', [4,.55,.12], [x,5.75,frontZ+.11], mats.dark);
  box(scene, 'warehouse glow', [2.4,.035,.04], [x,5.75,frontZ+.19], mirror ? mats.red : mats.cyan, false);
  for (let i=0;i<7;i++) {
    const y=.7+i*.85;
    box(scene,'side rib',[.14,.12,11],[x + (mirror?-6.65:6.65),y,z],mats.steel);
  }
  const light = new THREE.PointLight(mirror?0xff6548:0x79c6b0, 10, 15, 1.7);
  light.position.set(x,4,z+3); scene.add(light);
  addCollider(x,z,14,13,8);
}
function buildCrate(x,z,w,d,h,material) {
  const group = new THREE.Group(); group.position.set(x,0,z); scene.add(group);
  box(group,'crate body',[w,h,d],[0,h/2,0],material);
  const trim = mats.dark;
  for (const side of [-1,1]) {
    box(group,'crate rail',[.12,h+.06,d+.08],[side*(w/2-.14),h/2,0],trim);
    box(group,'crate rail',[w+.08,h+.06,.12],[0,h/2,side*(d/2-.14)],trim);
  }
  for (let i=-1;i<=1;i++) {
    box(group,'crate brace',[.14,h*.86,.17],[i*w*.27,h/2,0],mats.steel).rotation.z = i === 0 ? 0 : (i > 0 ? -.38 : .38);
  }
  box(group,'crate label',[.8,.4,.035],[0,h*.72,d/2+.025],mats.black,false);
  box(group,'crate label mark',[.36,.035,.02],[0,h*.74,d/2+.05],mats.yellow,false);
}
function buildBarrier(x,z,w) {
  const group = new THREE.Group(); group.position.set(x,0,z); scene.add(group);
  box(group,'concrete barrier',[w,1.1,.8],[0,.55,0],mats.concrete);
  box(group,'barrier cap',[w+.1,.12,.94],[0,1.12,0],mats.steel);
  for(let i=-1;i<=1;i++) box(group,'hazard stripe',[.36,.22,.02],[i*w*.3,.86,.416],mats.yellow,false);
}
function buildDrum(x,z) {
  cylinder(scene,'fuel drum',.55,.55,1.35,[x,.68,z],mats.orange,14);
  cylinder(scene,'drum rim',.57,.57,.09,[x,1.25,z],mats.steel,14);
  cylinder(scene,'drum base rim',.57,.57,.08,[x,.12,z],mats.steel,14);
  for(let y=.4;y<1.1;y+=.32) cylinder(scene,'drum rib',.565,.565,.055,[x,y,z],mats.dark,14);
  box(scene,'drum label',[.3,.28,.025],[x,.73,z+.552],mats.yellow,false);
}
function buildConsole(x,z) {
  box(scene,'relay console',[1.1,1.35,.8],[x,.68,z],mats.dark);
  box(scene,'console screen',[.8,.62,.06],[x,.95,z+.43],mats.cyan,false);
  box(scene,'console keyboard',[.72,.05,.22],[x,.42,z+.48],mats.steel,false);
  for(let i=0;i<3;i++) box(scene,'console indicator',[.08,.06,.02],[x-.2+i*.2,1.47,z+.42],i===1?mats.red:mats.cyan,false);
}

