const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find((target) => target.type === 'page');
if (!page) throw new Error('No browser page available');
const ws = new WebSocket(page.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});
ws.onmessage = ({ data }) => {
  const message = JSON.parse(data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
function send(method, params = {}) {
  const id = ++nextId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve) => pending.set(id, resolve));
}
async function evaluate(expression) {
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.result.exceptionDetails) throw new Error(result.result.exceptionDetails.text);
  return result.result.result.value;
}
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const errors = [];
ws.addEventListener('message', ({ data }) => {
  const message = JSON.parse(data);
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.text);
  if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') errors.push(message.params.entry.text);
});
await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await wait(700);
const menu = await evaluate("({title:document.title, menu:!document.querySelector('#main-menu').classList.contains('hidden'), canvas:!!document.querySelector('#game-canvas').getContext('webgl2')})");
await evaluate("document.querySelector('#deploy-btn').click()");
await wait(500);
const started = await evaluate("({hud:!document.querySelector('#hud').classList.contains('hidden'), wave:document.querySelector('#wave-label').textContent, enemies:document.querySelector('#enemies-left').textContent, ammo:document.querySelector('#ammo-val').textContent})");
await evaluate("document.querySelector('#game-canvas').dispatchEvent(new MouseEvent('mousedown',{button:0,bubbles:true}))");
const fired = await evaluate("document.querySelector('#ammo-val').textContent");
await evaluate("document.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyR',bubbles:true}))");
await wait(1800);
const reloaded = await evaluate("({ammo:document.querySelector('#ammo-val').textContent,reserve:document.querySelector('#reserve-val').textContent})");
await evaluate("document.dispatchEvent(new KeyboardEvent('keydown',{code:'Escape',bubbles:true}))");
const paused = await evaluate("!document.querySelector('#pause-menu').classList.contains('hidden')");
await evaluate("document.querySelector('#resume-btn').click()");
const resumed = await evaluate("document.querySelector('#pause-menu').classList.contains('hidden') && !document.querySelector('#hud').classList.contains('hidden')");
const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 70, captureBeyondViewport: false });
await import('node:fs/promises').then(({writeFile}) => writeFile('/tmp/opencode/blacksite-gameplay.jpg', Buffer.from(shot.result.data, 'base64')));
console.log(JSON.stringify({menu, started, ammoAfterShot: fired, reloaded, paused, resumed, errors}, null, 2));
ws.close();

