const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find((target) => target.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
ws.onmessage = ({data}) => { const m=JSON.parse(data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} };
function send(method,params={}) { const n=++id;ws.send(JSON.stringify({id:n,method,params}));return new Promise(r=>pending.set(n,r)); }
async function ev(expression) { const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw new Error(r.result.exceptionDetails.text);return r.result.result.value; }
const events=[];
ws.addEventListener('message',({data})=>{const m=JSON.parse(data);if(m.method==='Runtime.exceptionThrown')events.push({type:'exception',details:m.params.exceptionDetails});if(m.method==='Runtime.consoleAPICalled'&&m.params.type==='error')events.push({type:'console',args:m.params.args.map(a=>a.value||a.description)});if(m.method==='Network.responseReceived'&&m.params.response.status>=400)events.push({type:'http',url:m.params.response.url,status:m.params.response.status});});
await send('Runtime.enable');await send('Log.enable');await send('Network.enable');await send('Page.enable');
await ev("document.querySelector('#deploy-btn').click()");await ev("document.querySelector('#brief-deploy').click()");
await new Promise(r=>setTimeout(r,700));
await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:2,mobile:true});
await send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:5});
await new Promise(r=>setTimeout(r,250));
const metrics=await ev("({w:innerWidth,h:innerHeight,dpr:devicePixelRatio,touch:navigator.maxTouchPoints,controls:getComputedStyle(document.querySelector('.mobile-ui')).display,joystick:(()=>{let r=document.querySelector('#joystick').getBoundingClientRect();return [r.x,r.y,r.width,r.height]})(),fire:(()=>{let r=document.querySelector('#fire-btn').getBoundingClientRect();return [r.x,r.y,r.width,r.height]})(),hud:document.querySelector('#hud').getBoundingClientRect().toJSON()})");
console.log(JSON.stringify({metrics,events},null,2));ws.close();

