const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find((target) => target.type === 'page');
if (!page) throw new Error('No browser page available');
const ws = new WebSocket(page.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});
ws.onmessage = ({ data }) => {
  const message = JSON.parse(data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
function send(method, params = {}) {
  const id = ++nextId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve) => pending.set(id, resolve));
}
async function evaluate(expression) {
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.result.exceptionDetails) throw new Error(result.result.exceptionDetails.text);
  return result.result.result.value;
}
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const errors = [];
ws.addEventListener('message', ({ data }) => {
  const message = JSON.parse(data);
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.text);
  if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') errors.push(message.params.entry.text);
});
await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await wait(700);
const menu = await evaluate("({title:document.title, menu:!document.querySelector('#main-menu').classList.contains('hidden'), canvas:!!document.querySelector('#game-canvas').getContext('webgl2')})");
await evaluate("document.querySelector('#deploy-btn').click()");
await wait(100);
